import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.scheduling.annotation.AsyncConfigurer;
import org.springframework.scheduling.annotation.EnableAsync;
import org.springframework.scheduling.concurrent.ThreadPoolTaskExecutor;
import java.util.concurrent.Executor;

@Configuration
@EnableAsync
class AsyncConfig implements AsyncConfigurer {

    @Override
    public Executor getAsyncExecutor() {
        ThreadPoolTaskExecutor executor = new ThreadPoolTaskExecutor();
        executor.setCorePoolSize(4);
        executor.setMaxPoolSize(8);
        executor.setQueueCapacity(50);
        executor.initialize();
        return executor;
    }
}

import java.io.PrintWriter;
import java.util.List;
import java.util.stream.Collectors;

class OrderCsvExporter {

    void writeCsv(PrintWriter writer, List<Order> orders) {
        for (Order order : orders) {
            String[] row = { String.valueOf(order.getId()), order.getStatus(), String.valueOf(order.getTotal()) };
            writer.println(convertToCsvRow(row));
        }
    }

    private String convertToCsvRow(String[] fields) {
        return java.util.Arrays.stream(fields)
                .map(this::escapeSpecialCharacters)
                .collect(Collectors.joining(","));
    }

    private String escapeSpecialCharacters(String field) {
        String escaped = field.replace("\n", " ");
        if (escaped.contains(",") || escaped.contains("\"")) {
            escaped = "\"" + escaped.replace("\"", "\"\"") + "\"";
        }
        return escaped;
    }
}

